import manifestJson from './manifest.json';

import type { CoreToolsPlatform } from './platform';
import { type Version, parseVersion } from '../backend/versions';

type Manifest = {
    version: string;
    minimumVersion: string;
    releaseUrl: string;
    assets: { [rid: string]: { file: string, size: number, sha256: string } };
};

// The Azure Functions Core Tools release this extension downloads, pinned with the checksums of its archives.
// Generated by scripts/update-core-tools.mjs
export const CoreToolsManifest: Manifest = manifestJson;

// The oldest Azure Functions Core Tools an already installed copy may be, to be used instead of a download
export function getMinimumCoreToolsVersion(): Version {
    return parseVersion(CoreToolsManifest.minimumVersion)!;
}

// What to download for a platform
export type CoreToolsDownload = {
    version: string;
    file: string;
    url: string;
    size: number;
    sha256: string;
};

export function getCoreToolsDownload(platform: CoreToolsPlatform, manifest: Manifest = CoreToolsManifest): CoreToolsDownload | undefined {

    const asset = manifest.assets[platform.rid];
    if (!asset) {
        return undefined;
    }

    return {
        version: manifest.version,
        file: asset.file,
        url: `${manifest.releaseUrl}/${asset.file}`,
        size: asset.size,
        sha256: asset.sha256
    };
}
